import { parseWorldModifierLevelConfig } from "../world-modifiers/WorldModifierLevelConfig";
import type { WorldModifierConfiguration } from "../world-modifiers/WorldModifierDefinition";

/** Generated by the Figma importer. Only *-config.json files are loaded here. */
const modules = import.meta.glob("../levels/*-config.json", { eager: true, import: "default" }) as Record<string, unknown>;
const configs = new Map<string, WorldModifierConfiguration>();
for (const [path, data] of Object.entries(modules)) {
    const name = path.split("/").pop() ?? "";
    const levelId = name.slice(0, -"-config.json".length);
    configs.set(levelId, parseWorldModifierLevelConfig(data, path).worldModifier);
}
/** A missing config intentionally disables world modifiers for that level. */
export function getLevelWorldModifierConfig(levelId: string): WorldModifierConfiguration | undefined {
    return configs.get(levelId);
}
